 15→)
 16→
 17→// Session state management functions shared across all strategies.
 18→// SessionState is stored in .git/entire-sessions/{session_id}.json
 19→
 20→// getSessionStateDir returns the path to the session state directory.
 21→// This is stored in the git common dir so it's shared across all worktrees.
 22→func getSessionStateDir(ctx context.Context) (string, error) {
 23→	commonDir, err := GetGitCommonDir(ctx)
 24→	if err != nil {
 25→		return "", err
 26→	}
 27→	return filepath.Join(commonDir, session.SessionStateDirName), nil
 28→}
 29→
 30→// sessionStateFile returns the path to a session state file.
 31→func sessionStateFile(ctx context.Context, sessionID string) (string, error) {
 32→	stateDir, err := getSessionStateDir(ctx)
 33→	if err != nil {
 34→		return "", err
 35→	}
 36→	return filepath.Join(stateDir, sessionID+".json"), nil
 37→}
 38→
 39→// LoadSessionState loads the session state for the given session ID.
 40→// Returns (nil, nil) when session file doesn't exist or session is stale (not an error condition).
 41→// Stale sessions are automatically deleted by the underlying StateStore.
 42→func LoadSessionState(ctx context.Context, sessionID string) (*SessionState, error) {
 43→	store, err := session.NewStateStore(ctx)
 44→	if err != nil {
 45→		return nil, fmt.Errorf("failed to create state store: %w", err)
 46→	}
 47→
 48→	state, err := store.Load(ctx, sessionID)
 49→	if err != nil {
 50→		return nil, fmt.Errorf("failed to load session state: %w", err)
 51→	}
 52→	return state, nil
 53→}
 54→
 55→// SaveSessionState saves the session state atomically.
 56→func SaveSessionState(ctx context.Context, state *SessionState) error {
 57→	// Validate session ID to prevent path traversal
 58→	if err := validation.ValidateSessionID(state.SessionID); err != nil {
 59→		return fmt.Errorf("invalid session ID: %w", err)
 60→	}
 61→
 62→	stateDir, err := getSessionStateDir(ctx)
 63→	if err != nil {
 64→		return fmt.Errorf("failed to get session state directory: %w", err)
 65→	}
 66→
 67→	if err := os.MkdirAll(stateDir, 0o750); err != nil {
 68→		return fmt.Errorf("failed to create session state directory: %w", err)
 69→	}
 70→
 71→	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
 72→	if err != nil {
 73→		return fmt.Errorf("failed to marshal session state: %w", err)
 74→	}
 75→
 76→	stateFile, err := sessionStateFile(ctx, state.SessionID)
 77→	if err != nil {
 78→		return fmt.Errorf("failed to get session state file path: %w", err)
 79→	}
 80→
 81→	// Atomic write: write to temp file, then rename
 82→	tmpFile := stateFile + ".tmp"
 83→	if err := os.WriteFile(tmpFile, data, 0o600); err != nil {
 84→		return fmt.Errorf("failed to write session state: %w", err)
 85→	}
 86→	if err := os.Rename(tmpFile, stateFile); err != nil {
 87→		return fmt.Errorf("failed to rename session state file: %w", err)
 88→	}
 89→	return nil
 90→}
 91→
 92→// ListSessionStates returns all session states from the state directory.
 93→// This is a package-level function that doesn't require a specific strategy instance.
 94→func ListSessionStates(ctx context.Context) ([]*SessionState, error) {
 95→	store, err := session.NewStateStore(ctx)
 96→	if err != nil {
 97→		return nil, fmt.Errorf("failed to create state store: %w", err)
 98→	}
 99→
100→	states, err := store.List(ctx)
101→	if err != nil {
102→		return nil, fmt.Errorf("failed to list session states: %w", err)
103→	}
104→	return states, nil
105→}
106→
107→// FindMostRecentSession returns the session ID of the most recently interacted session
108→// (by LastInteractionTime) in the current worktree. Returns empty string if no sessions exist.
109→// Scoping to the current worktree prevents cross-worktree pollution in log routing.
110→// Falls back to unfiltered search if the worktree path can't be determined.
111→func FindMostRecentSession(ctx context.Context) string {
112→	states, err := ListSessionStates(ctx)
113→	if err != nil || len(states) == 0 {
114→		return ""
115→	}
116→
117→	// Scope to current worktree to prevent cross-worktree pollution.
118→	worktreePath, wpErr := paths.WorktreeRoot(ctx)
119→	if wpErr == nil && worktreePath != "" {
120→		var filtered []*SessionState
121→		for _, s := range states {
122→			if s.WorktreePath == worktreePath {
123→				filtered = append(filtered, s)
124→			}
125→		}
126→		if len(filtered) > 0 {
127→			states = filtered
128→		}
129→		// If no sessions match the worktree, fall back to all sessions
130→	}
131→
132→	var best *SessionState
133→	for _, s := range states {
134→		if s.LastInteractionTime == nil {
135→			continue
136→		}
137→		if best == nil || s.LastInteractionTime.After(*best.LastInteractionTime) {
138→			best = s
139→		}
140→	}
141→	if best != nil {
142→		return best.SessionID
143→	}
144→
145→	// Fallback: return most recently started session
146→	for _, s := range states {
147→		if best == nil || s.StartedAt.After(best.StartedAt) {
148→			best = s
149→		}
150→	}
151→	if best != nil {
152→		return best.SessionID
153→	}
154→	return ""
155→}
156→
157→// TransitionAndLog runs a session phase transition, applies actions via the
158→// handler, and logs the transition. Returns the first handler error from
159→// ApplyTransition (if any) so callers can surface it. The error is also
160→// logged internally for diagnostics.
161→// This is the single entry point for all state machine transitions to ensure
162→// consistent logging of phase changes.
163→func TransitionAndLog(goCtx context.Context, state *SessionState, event session.Event, ctx session.TransitionContext, handler session.ActionHandler) error {
164→	oldPhase := state.Phase
165→	result := session.Transition(oldPhase, event, ctx)
166→	logCtx := logging.WithComponent(goCtx, "session")
167→
168→	handlerErr := session.ApplyTransition(goCtx, state, result, handler)
169→	if handlerErr != nil {
170→		logging.Error(logCtx, "action handler error during transition",
171→			slog.String("session_id", state.SessionID),
172→			slog.String("event", event.String()),
173→			slog.Any("error", handlerErr),
174→		)
175→	}
176→
177→	if result.NewPhase != oldPhase {
178→		logging.Info(logCtx, "phase transition",
179→			slog.String("session_id", state.SessionID),
180→			slog.String("event", event.String()),
181→			slog.String("from", string(oldPhase)),
182→			slog.String("to", string(result.NewPhase)),
183→		)
184→	} else {
185→		logging.Debug(logCtx, "phase unchanged",
186→			slog.String("session_id", state.SessionID),
187→			slog.String("event", event.String()),
188→			slog.String("phase", string(result.NewPhase)),
189→			slog.Any("result", result),
190→		)
191→	}
192→
193→	if handlerErr != nil {
194→		return fmt.Errorf("transition %s: %w", event, handlerErr)
195→	}
196→	return nil
197→}
198→
199→// ClearSessionState removes the session state file for the given session ID.
200→func ClearSessionState(ctx context.Context, sessionID string) error {
201→	// Validate session ID to prevent path traversal
202→	if err := validation.ValidateSessionID(sessionID); err != nil {
203→		return fmt.Errorf("invalid session ID: %w", err)
204→	}
205→
206→	stateFile, err := sessionStateFile(ctx, sessionID)
207→	if err != nil {
208→		return fmt.Errorf("failed to get session state file path: %w", err)
209→	}
210→
211→	if err := os.Remove(stateFile); err != nil {
212→		if os.IsNotExist(err) {
213→			return nil // Already gone, not an error
214→		}
215→		return fmt.Errorf("failed to remove session state file: %w", err)
216→	}
217→	return nil
218→}
