 78→// ReadTranscript reads the raw JSONL transcript bytes for a session.
 79→func (c *ClaudeCodeAgent) ReadTranscript(sessionRef string) ([]byte, error) {
 80→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
 81→	if err != nil {
 82→		return nil, fmt.Errorf("failed to read transcript: %w", err)
 83→	}
 84→	return data, nil
 85→}
 86→
 87→// ExtractPrompts extracts user prompts from the transcript starting at the given line offset.
 88→func (c *ClaudeCodeAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
 89→	lines, err := transcript.ParseFromFileAtLine(sessionRef, fromOffset)
 90→	if err != nil {
 91→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
 92→	}
 93→
 94→	var prompts []string
 95→	for i := range lines {
 96→		if lines[i].Type != transcript.TypeUser {
 97→			continue
 98→		}
 99→		content := transcript.ExtractUserContent(lines[i].Message)
100→		if content != "" {
101→			prompts = append(prompts, textutil.StripIDEContextTags(content))
102→		}
103→	}
104→	return prompts, nil
105→}
106→
107→// ExtractSummary extracts the last assistant message as a session summary.
108→func (c *ClaudeCodeAgent) ExtractSummary(sessionRef string) (string, error) {
109→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
110→	if err != nil {
111→		return "", fmt.Errorf("failed to read transcript: %w", err)
112→	}
113→
114→	lines, parseErr := transcript.ParseFromBytes(data)
115→	if parseErr != nil {
116→		return "", fmt.Errorf("failed to parse transcript: %w", parseErr)
117→	}
118→
119→	// Walk backward to find last assistant text block
120→	for i := len(lines) - 1; i >= 0; i-- {
121→		if lines[i].Type != transcript.TypeAssistant {
122→			continue
123→		}
124→		var msg transcript.AssistantMessage
125→		if err := json.Unmarshal(lines[i].Message, &msg); err != nil {
126→			continue
127→		}
128→		for _, block := range msg.Content {
129→			if block.Type == transcript.ContentTypeText && block.Text != "" {
130→				return block.Text, nil
131→			}
132→		}
133→	}
134→	return "", nil
135→}
