137→// PrepareTranscript waits for Claude Code's async transcript flush to complete.
138→// Claude writes a hook_progress sentinel entry after flushing all pending writes.
139→func (c *ClaudeCodeAgent) PrepareTranscript(ctx context.Context, sessionRef string) error {
140→	waitForTranscriptFlush(ctx, sessionRef, time.Now())
141→	return nil
142→}
