144→// CalculateTokenUsage computes token usage from the transcript starting at the given line offset.
145→func (c *ClaudeCodeAgent) CalculateTokenUsage(transcriptData []byte, fromOffset int) (*agent.TokenUsage, error) {
146→	return c.CalculateTotalTokenUsage(transcriptData, fromOffset, "")
147→}
