238→// --- Transcript flush sentinel ---
239→
240→// stopHookSentinel is the string that appears in Claude Code's hook_progress
241→// entry when the stop hook has been invoked, indicating the transcript is fully flushed.
242→const stopHookSentinel = "hooks claude-code stop"
243→
244→// waitForTranscriptFlush polls the transcript file for the stop hook sentinel.
245→// Falls back silently after a timeout.
246→func waitForTranscriptFlush(ctx context.Context, transcriptPath string, hookStartTime time.Time) {
247→	const (
248→		maxWait      = 3 * time.Second
249→		pollInterval = 50 * time.Millisecond
250→		tailBytes    = 4096
251→		maxSkew      = 2 * time.Second
252→	)
253→
254→	logCtx := logging.WithComponent(ctx, "agent.claudecode")
255→
256→	// Fast path: skip the poll loop when the sentinel can't possibly appear.
257→	// - File doesn't exist: nothing to poll.
258→	// - File is stale (unmodified for 2+ min): agent isn't running anymore.
259→	//   This avoids 3s timeouts per stale "active" session (e.g., agent crashed
260→	//   without firing stop hook).
261→	const staleThreshold = 2 * time.Minute
262→	info, err := os.Stat(transcriptPath)
263→	if err != nil {
264→		// Most likely the file doesn't exist; other errors (permission, etc.)
265→		// would also prevent polling, so skip the wait either way.
266→		return
267→	}
268→	fileAge := time.Since(info.ModTime())
269→	if fileAge > staleThreshold {
270→		logging.Debug(logCtx, "transcript file is stale, skipping sentinel wait",
271→			slog.Duration("file_age", fileAge),
272→		)
273→		return
274→	}
275→
276→	deadline := time.Now().Add(maxWait)
277→	for time.Now().Before(deadline) {
278→		if checkStopSentinel(transcriptPath, tailBytes, hookStartTime, maxSkew) {
279→			logging.Debug(logCtx, "transcript flush sentinel found",
280→				slog.Duration("wait", time.Since(hookStartTime)),
281→			)
282→			return
283→		}
284→		time.Sleep(pollInterval)
285→	}
286→	logging.Warn(logCtx, "transcript flush sentinel not found within timeout, proceeding",
287→		slog.Duration("timeout", maxWait),
288→	)
289→}
290→
291→// checkStopSentinel reads the tail of the transcript file and looks for the sentinel.
292→func checkStopSentinel(path string, tailBytes int64, hookStartTime time.Time, maxSkew time.Duration) bool {
293→	f, err := os.Open(path) //nolint:gosec // path comes from agent hook input
294→	if err != nil {
295→		return false
296→	}
297→	defer f.Close()
298→
299→	info, err := f.Stat()
300→	if err != nil {
301→		return false
302→	}
303→	offset := info.Size() - tailBytes
304→	if offset < 0 {
305→		offset = 0
306→	}
307→	buf := make([]byte, info.Size()-offset)
308→	if _, err := f.ReadAt(buf, offset); err != nil {
309→		return false
310→	}
311→
312→	lines := strings.Split(string(buf), "\n")
313→	for _, line := range lines {
314→		line = strings.TrimSpace(line)
315→		if line == "" || !strings.Contains(line, stopHookSentinel) {
316→			continue
317→		}
318→
319→		var entry struct {
320→			Timestamp string `json:"timestamp"`
321→		}
322→		if json.Unmarshal([]byte(line), &entry) != nil || entry.Timestamp == "" {
323→			continue
324→		}
325→		ts, err := time.Parse(time.RFC3339Nano, entry.Timestamp)
326→		if err != nil {
327→			ts, err = time.Parse(time.RFC3339, entry.Timestamp)
328→			if err != nil {
329→				continue
330→			}
331→		}
332→		// Validate timestamp is within acceptable range:
333→		// - Not too far in the past (before hook started minus skew)
334→		// - Not too far in the future (after hook started plus skew)
335→		lowerBound := hookStartTime.Add(-maxSkew)
336→		upperBound := hookStartTime.Add(maxSkew)
337→		if ts.After(lowerBound) && ts.Before(upperBound) {
338→			return true
339→		}
340→	}
341→	return false
342→}
