 19→
 20→// HookNames returns the hook verbs Gemini CLI supports.
 21→// These become subcommands: entire hooks gemini <verb>
 22→func (g *GeminiCLIAgent) HookNames() []string {
 23→	return []string{
 24→		HookNameSessionStart,
 25→		HookNameSessionEnd,
 26→		HookNameBeforeAgent,
 27→		HookNameAfterAgent,
 28→		HookNameBeforeModel,
 29→		HookNameAfterModel,
 30→		HookNameBeforeToolSelection,
 31→		HookNameBeforeTool,
 32→		HookNameAfterTool,
 33→		HookNamePreCompress,
 34→		HookNameNotification,
 35→	}
 36→}
 37→
 38→// ParseHookEvent translates a Gemini CLI hook into a normalized lifecycle Event.
 39→// Returns nil if the hook has no lifecycle significance (e.g., pass-through hooks).
 40→func (g *GeminiCLIAgent) ParseHookEvent(_ context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
 41→	switch hookName {
 42→	case HookNameSessionStart:
 43→		return g.parseSessionStart(stdin)
 44→	case HookNameBeforeAgent:
 45→		return g.parseTurnStart(stdin)
 46→	case HookNameAfterAgent:
 47→		return g.parseTurnEnd(stdin)
 48→	case HookNameSessionEnd:
 49→		return g.parseSessionEnd(stdin)
 50→	case HookNamePreCompress:
 51→		return g.parseCompaction(stdin)
 52→	case HookNameBeforeTool, HookNameAfterTool, HookNameBeforeModel,
 53→		HookNameAfterModel, HookNameBeforeToolSelection, HookNameNotification:
 54→		// Acknowledged hooks with no lifecycle action
 55→		return nil, nil //nolint:nilnil // nil event = no lifecycle action
 56→	default:
 57→		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
 58→	}
 59→}
 60→
 61→// ReadTranscript reads the raw JSON transcript bytes for a session.
 62→func (g *GeminiCLIAgent) ReadTranscript(sessionRef string) ([]byte, error) {
 63→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
 64→	if err != nil {
 65→		return nil, fmt.Errorf("failed to read transcript: %w", err)
 66→	}
 67→	return data, nil
 68→}
 69→
 70→// ExtractPrompts extracts user prompts from the transcript starting at the given message offset.
 71→func (g *GeminiCLIAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
 72→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
 73→	if err != nil {
 74→		return nil, fmt.Errorf("failed to read transcript: %w", err)
 75→	}
 76→
 77→	t, parseErr := ParseTranscript(data)
 78→	if parseErr != nil {
 79→		return nil, fmt.Errorf("failed to parse transcript: %w", parseErr)
 80→	}
 81→
 82→	var prompts []string
 83→	for i := fromOffset; i < len(t.Messages); i++ {
 84→		msg := t.Messages[i]
 85→		if msg.Type == MessageTypeUser && msg.Content != "" {
 86→			prompts = append(prompts, msg.Content)
 87→		}
 88→	}
 89→	return prompts, nil
 90→}
 91→
 92→// ExtractSummary extracts the last assistant message as a session summary.
 93→func (g *GeminiCLIAgent) ExtractSummary(sessionRef string) (string, error) {
 94→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
 95→	if err != nil {
 96→		return "", fmt.Errorf("failed to read transcript: %w", err)
 97→	}
 98→	return ExtractLastAssistantMessage(data)
 99→}
100→
101→// CalculateTokenUsage computes token usage from the transcript starting at the given message offset.
102→func (g *GeminiCLIAgent) CalculateTokenUsage(transcriptData []byte, fromOffset int) (*agent.TokenUsage, error) {
103→	var transcript struct {
104→		Messages []geminiMessageWithTokens `json:"messages"`
105→	}
106→
107→	if err := json.Unmarshal(transcriptData, &transcript); err != nil {
108→		return &agent.TokenUsage{}, fmt.Errorf("failed to parse transcript for token usage: %w", err)
109→	}
110→
111→	usage := &agent.TokenUsage{}
112→
113→	for i, msg := range transcript.Messages {
114→		// Skip messages before startMessageIndex
115→		if i < fromOffset {
116→			continue
117→		}
118→
119→		// Only count tokens from gemini (assistant) messages
120→		if msg.Type != MessageTypeGemini {
121→			continue
122→		}
123→
124→		if msg.Tokens == nil {
125→			continue
126→		}
127→
128→		usage.APICallCount++
129→		usage.InputTokens += msg.Tokens.Input
130→		usage.OutputTokens += msg.Tokens.Output
131→		usage.CacheReadTokens += msg.Tokens.Cached
132→	}
133→
134→	return usage, nil
135→}
