  1→package factoryaidroid
  2→
  3→import (
  4→	"bufio"
  5→	"bytes"
  6→	"encoding/json"
  7→	"fmt"
  8→	"io"
  9→	"os"
 10→	"path/filepath"
 11→	"slices"
 12→	"strings"
 13→
 14→	"github.com/entireio/cli/cmd/entire/cli/agent"
 15→	"github.com/entireio/cli/cmd/entire/cli/transcript"
 16→)
 17→
 18→// TranscriptLine is an alias to the shared transcript.Line type.
 19→type TranscriptLine = transcript.Line
 20→
 21→// droidEnvelope is the top-level structure of a Factory AI Droid JSONL line.
 22→// Droid wraps messages as {"type":"message","id":"...","message":{"role":"assistant","content":[...]}},
 23→// unlike Claude Code which uses {"type":"assistant","uuid":"...","message":{"content":[...]}}.
 24→type droidEnvelope struct {
 25→	Type    string          `json:"type"`
 26→	ID      string          `json:"id"`
 27→	Message json.RawMessage `json:"message"`
 28→}
 29→
 30→// droidMessageRole extracts just the role from the inner message.
 31→type droidMessageRole struct {
 32→	Role string `json:"role"`
 33→}
 34→
 35→// ParseDroidTranscript parses a Droid JSONL file into normalized transcript.Line entries.
 36→// It transforms the Droid envelope format (type="message", role inside message) into the
 37→// shared transcript.Line format (type="assistant"/"user", message=inner content).
 38→// Non-message entries (session_start, etc.) are skipped.
 39→func ParseDroidTranscript(path string, startLine int) ([]transcript.Line, int, error) {
 40→	file, err := os.Open(path) //nolint:gosec // path is a controlled transcript file path
 41→	if err != nil {
 42→		return nil, 0, fmt.Errorf("failed to open transcript: %w", err)
 43→	}
 44→	defer func() { _ = file.Close() }()
 45→
 46→	return parseDroidTranscriptFromReader(file, startLine)
 47→}
 48→
 49→// ParseDroidTranscriptFromBytes parses Droid JSONL content from a byte slice.
 50→// startLine skips the first N raw JSONL lines before parsing (0 = parse all).
 51→// Returns parsed lines, total raw line count, and any error.
 52→// This mirrors ParseDroidTranscript's startLine parameter, applying the offset
 53→// at the raw line level before filtering out non-message entries.
 54→func ParseDroidTranscriptFromBytes(content []byte, startLine int) ([]transcript.Line, int, error) {
 55→	return parseDroidTranscriptFromReader(bytes.NewReader(content), startLine)
 56→}
 57→
 58→func parseDroidTranscriptFromReader(r io.Reader, startLine int) ([]transcript.Line, int, error) {
 59→	reader := bufio.NewReader(r)
 60→	var lines []transcript.Line
 61→	totalLines := 0
 62→
 63→	for {
 64→		lineBytes, err := reader.ReadBytes('\n')
 65→		if err != nil && err != io.EOF {
 66→			return nil, 0, fmt.Errorf("failed to read transcript: %w", err)
 67→		}
 68→
 69→		if len(lineBytes) == 0 {
 70→			if err == io.EOF {
 71→				break
 72→			}
 73→			continue
 74→		}
 75→
 76→		if totalLines >= startLine {
 77→			if line, ok := parseDroidLine(lineBytes); ok {
 78→				lines = append(lines, line)
 79→			}
 80→		}
 81→		totalLines++
 82→
 83→		if err == io.EOF {
 84→			break
 85→		}
 86→	}
 87→
 88→	return lines, totalLines, nil
 89→}
 90→
 91→// parseDroidLine converts a single Droid JSONL line into a normalized transcript.Line.
 92→// Returns false if the line is not a message entry (e.g., session_start).
 93→func parseDroidLine(lineBytes []byte) (transcript.Line, bool) {
 94→	var env droidEnvelope
 95→	if err := json.Unmarshal(lineBytes, &env); err != nil {
 96→		return transcript.Line{}, false
 97→	}
 98→
 99→	// Only process "message" type entries — skip session_start, etc.
100→	if env.Type != "message" {
101→		return transcript.Line{}, false
102→	}
103→
104→	// Extract role from the inner message
105→	var role droidMessageRole
106→	if err := json.Unmarshal(env.Message, &role); err != nil {
107→		return transcript.Line{}, false
108→	}
109→
110→	return transcript.Line{
111→		Type:    role.Role, // "assistant" or "user"
112→		UUID:    env.ID,
113→		Message: env.Message,
114→	}, true
115→}
116→
117→// ExtractModifiedFiles extracts files modified by tool calls from transcript.
118→func ExtractModifiedFiles(lines []TranscriptLine) []string {
119→	fileSet := make(map[string]bool)
120→	var files []string
121→
122→	for _, line := range lines {
123→		if line.Type != "assistant" {
124→			continue
125→		}
126→
127→		var msg transcript.AssistantMessage
128→		if err := json.Unmarshal(line.Message, &msg); err != nil {
129→			continue
130→		}
131→
132→		for _, block := range msg.Content {
133→			if block.Type != "tool_use" || !slices.Contains(FileModificationTools, block.Name) {
134→				continue
135→			}
136→
137→			var input transcript.ToolInput
138→			if err := json.Unmarshal(block.Input, &input); err != nil {
139→				continue
140→			}
141→
142→			file := input.FilePath
143→			if file == "" {
144→				file = input.NotebookPath
145→			}
146→
147→			if file != "" && !fileSet[file] {
148→				fileSet[file] = true
149→				files = append(files, file)
150→			}
151→		}
152→	}
153→
154→	return files
155→}
156→
157→// CalculateTokenUsage calculates token usage from a Factory AI Droid transcript.
158→// Due to streaming, multiple transcript rows may share the same message.id.
159→// We deduplicate by taking the row with the highest output_tokens for each message.id.
160→func CalculateTokenUsage(transcriptLines []TranscriptLine) *agent.TokenUsage {
161→	// Map from message.id to the usage with highest output_tokens
162→	usageByMessageID := make(map[string]messageUsage)
163→
164→	for _, line := range transcriptLines {
165→		if line.Type != "assistant" {
166→			continue
167→		}
168→
169→		var msg messageWithUsage
170→		if err := json.Unmarshal(line.Message, &msg); err != nil {
171→			continue
172→		}
173→
174→		if msg.ID == "" {
175→			continue
176→		}
177→
178→		// Keep the entry with highest output_tokens (final streaming state)
179→		existing, exists := usageByMessageID[msg.ID]
180→		if !exists || msg.Usage.OutputTokens > existing.OutputTokens {
181→			usageByMessageID[msg.ID] = msg.Usage
182→		}
183→	}
184→
185→	// Sum up all unique messages
186→	usage := &agent.TokenUsage{
187→		APICallCount: len(usageByMessageID),
188→	}
189→	for _, u := range usageByMessageID {
190→		usage.InputTokens += u.InputTokens
191→		usage.CacheCreationTokens += u.CacheCreationInputTokens
192→		usage.CacheReadTokens += u.CacheReadInputTokens
193→		usage.OutputTokens += u.OutputTokens
194→	}
195→
196→	return usage
197→}
