214→// ExtractSpawnedAgentIDs extracts agent IDs from Task tool results in a transcript.
215→// When a Task tool completes, the tool_result contains "agentId: <id>" in its content.
216→// Returns a map of agentID -> toolUseID for all spawned agents.
217→func ExtractSpawnedAgentIDs(transcriptLines []TranscriptLine) map[string]string {
218→	agentIDs := make(map[string]string)
219→
220→	for _, line := range transcriptLines {
221→		if line.Type != "user" {
222→			continue
223→		}
224→
225→		// Parse as array of content blocks (tool results)
226→		var contentBlocks []struct {
227→			Type      string          `json:"type"`
228→			ToolUseID string          `json:"tool_use_id"`
229→			Content   json.RawMessage `json:"content"`
230→		}
231→
232→		var msg struct {
233→			Content json.RawMessage `json:"content"`
234→		}
235→		if err := json.Unmarshal(line.Message, &msg); err != nil {
236→			continue
237→		}
238→
239→		if err := json.Unmarshal(msg.Content, &contentBlocks); err != nil {
240→			continue
241→		}
242→
243→		for _, block := range contentBlocks {
244→			if block.Type != "tool_result" {
245→				continue
246→			}
247→
248→			// Content can be a string or array of text blocks
249→			var textContent string
250→
251→			// Try as array of text blocks first
252→			var textBlocks []struct {
253→				Type string `json:"type"`
254→				Text string `json:"text"`
255→			}
256→			if err := json.Unmarshal(block.Content, &textBlocks); err == nil {
257→				var sb strings.Builder
258→				for _, tb := range textBlocks {
259→					if tb.Type == "text" {
260→						sb.WriteString(tb.Text + "\n")
261→					}
262→				}
263→				textContent = sb.String()
264→			} else {
265→				// Try as plain string
266→				var str string
267→				if err := json.Unmarshal(block.Content, &str); err == nil {
268→					textContent = str
269→				}
270→			}
271→
272→			// Look for agentId in the text
273→			if agentID := extractAgentIDFromText(textContent); agentID != "" {
274→				agentIDs[agentID] = block.ToolUseID
275→			}
276→		}
277→	}
278→
279→	return agentIDs
280→}
