288→// ExtractModelFromTranscript extracts the LLM model name from the Factory AI Droid
289→// session settings file. Factory AI Droid stores a .settings.json file alongside
290→// each transcript JSONL (e.g., <session-id>.settings.json next to <session-id>.jsonl).
291→// The settings file contains the actual model being used, unlike the transcript's
292→// system-reminder text which can be stale after provider switches.
293→// Returns empty string if the settings file cannot be read or has no model.
294→func ExtractModelFromTranscript(transcriptPath string) string {
295→	if transcriptPath == "" {
296→		return ""
297→	}
298→
299→	settingsPath := strings.TrimSuffix(transcriptPath, ".jsonl") + ".settings.json"
300→	data, err := os.ReadFile(settingsPath) //nolint:gosec // Path derived from agent hook input
301→	if err != nil {
302→		return ""
303→	}
304→
305→	var settings droidSettings
306→	if err := json.Unmarshal(data, &settings); err != nil {
307→		return ""
308→	}
309→
310→	return cleanModelName(settings.Model)
311→}
