313→// cleanModelName normalizes a Factory AI Droid model identifier into a display name.
314→// For example, "custom:Gemini-2.5-Pro-0" becomes "Gemini-2.5-Pro-0".
315→func cleanModelName(raw string) string {
316→	// Strip known prefixes that Factory AI Droid adds to model identifiers
317→	if after, found := strings.CutPrefix(raw, "custom:"); found {
318→		return after
319→	}
320→	return raw
321→}
