323→// extractAgentIDFromText extracts an agent ID from text containing "agentId: <id>".
324→func extractAgentIDFromText(text string) string {
325→	const prefix = "agentId: "
326→	idx := strings.Index(text, prefix)
327→	if idx == -1 {
328→		return ""
329→	}
330→
331→	// Extract the ID (alphanumeric characters after the prefix)
332→	start := idx + len(prefix)
333→	end := start
334→	for end < len(text) && (text[end] >= 'a' && text[end] <= 'z' ||
335→		text[end] >= 'A' && text[end] <= 'Z' ||
336→		text[end] >= '0' && text[end] <= '9') {
337→		end++
338→	}
339→
340→	if end > start {
341→		return text[start:end]
342→	}
343→	return ""
344→}
