425→// CalculateTotalTokenUsageFromTranscript calculates token usage for a turn, including subagents.
426→// It parses the main transcript from startLine, extracts spawned agent IDs,
427→// and calculates their token usage from transcripts in subagentsDir.
428→func CalculateTotalTokenUsageFromTranscript(transcriptPath string, startLine int, subagentsDir string) (*agent.TokenUsage, error) {
429→	if transcriptPath == "" {
430→		return &agent.TokenUsage{}, nil
431→	}
432→
433→	// Parse transcript once using Droid-specific parser
434→	parsed, _, err := ParseDroidTranscript(transcriptPath, startLine)
435→	if err != nil {
436→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
437→	}
438→
439→	// Calculate token usage from parsed transcript
440→	mainUsage := CalculateTokenUsage(parsed)
441→
442→	// Extract spawned agent IDs from the same parsed transcript
443→	agentIDs := ExtractSpawnedAgentIDs(parsed)
444→
445→	// Calculate subagent token usage
446→	if len(agentIDs) > 0 {
447→		subagentUsage := &agent.TokenUsage{}
448→		for agentID := range agentIDs {
449→			agentPath := filepath.Join(subagentsDir, fmt.Sprintf("agent-%s.jsonl", agentID))
450→			agentUsage, err := CalculateTokenUsageFromFile(agentPath, 0)
451→			if err != nil {
452→				// Agent transcript may not exist yet or may have been cleaned up
453→				continue
454→			}
455→			subagentUsage.InputTokens += agentUsage.InputTokens
456→			subagentUsage.CacheCreationTokens += agentUsage.CacheCreationTokens
457→			subagentUsage.CacheReadTokens += agentUsage.CacheReadTokens
458→			subagentUsage.OutputTokens += agentUsage.OutputTokens
459→			subagentUsage.APICallCount += agentUsage.APICallCount
460→		}
461→		if subagentUsage.APICallCount > 0 {
462→			mainUsage.SubagentTokens = subagentUsage
463→		}
464→	}
465→
466→	return mainUsage, nil
467→}
