// handleLifecycleModelUpdate persists the model name so that subsequent hooks
// (which run as separate CLI processes) can pick it up.
//
// If the session state file already exists (e.g., Gemini's BeforeModel fires
// after TurnStart), the model is written directly to state.ModelName.
// Otherwise a lightweight hint file is used to bridge the cross-process gap
// (e.g., Claude Code's SessionStart fires before any TurnStart).
func handleLifecycleModelUpdate(ctx context.Context, ag agent.Agent, event *agent.Event) error {
	logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
	logging.Info(logCtx, "model-update",
		slog.String("session_id", event.SessionID),
		slog.String("model", event.Model),
	)

	if event.SessionID == "" || event.Model == "" {
		return nil
	}

	// Try to update session state directly (works when state file already exists)
	if state, err := strategy.LoadSessionState(ctx, event.SessionID); err == nil && state != nil {
		state.ModelName = event.Model
		if saveErr := strategy.SaveSessionState(ctx, state); saveErr != nil {
			logging.Warn(logCtx, "failed to update session state with model",
				slog.String("error", saveErr.Error()))
		}
		return nil
	}

	// State doesn't exist yet — fall back to hint file for cross-process persistence
	if err := strategy.StoreModelHint(ctx, event.SessionID, event.Model); err != nil {
		logging.Warn(logCtx, "failed to store model hint",
			slog.String("error", err.Error()))
	}

	return nil
}

